return ['domain'=>'tranzly','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Vícejazyčný WordPress, jeden příspěvek na jazyk: propojené překlady příspěvků, stránek, kategorií, textu médií, widgetů a názvu webu s importovanými starými překlady Tranzly.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Poskytovatelé AI','The makers of ChatGPT. A good all-rounder.'=>'Tvůrci ChatGPT. Dobrý všestranný nástroj.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvůrci systému Claude. Silní v psaní a pečlivém uvažování.','Google\'s Gemini models. Fast and inexpensive.'=>'Modely Gemini od společnosti Google. Rychlé a levné.','A European AI company with fast, inexpensive models.'=>'Evropská společnost zabývající se umělou inteligencí s rychlými a levnými modely.','Low-cost models that are good at writing and code.'=>'Cenově dostupné modely, které jsou dobré v psaní a kódování.','One key for models from many different providers.'=>'Jedno klíčové slovo pro modely od mnoha různých poskytovatelů.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Jakákoli služba, která funguje jako API OpenAI, včetně modelu spuštěného ve vašem vlastním počítači nebo serveru.','General (used when nothing more specific is set)'=>'Obecné (použije se, když není nastaveno nic specifičtějšího)','Writing and rewriting'=>'Zápis a přepis','Translation'=>'Překlad','Code and CSS'=>'Kód a CSS','Sorry, you are not allowed to access this page.'=>'Litujeme, nemáte oprávnění k přístupu na tuto stránku.','These settings are shared by every plugin that uses them: %s.'=>'Tato nastavení sdílí každý plugin, který je používá: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaše klíče jsou zašifrovány v databázi tohoto webu a jsou odesílány pouze poskytovateli, kterého jste si vybrali – nám je neposíláme nikdy.','Step 1 of 2: choose an AI provider'=>'Krok 1 ze 2: vyberte poskytovatele AI','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Používáte vlastní klíč, takže za to, co spotřebujete, platíte přímo poskytovateli. Nejste si jistí? Funguje kterákoli z těchto možností; další můžete přidat později.','Next'=>'Další','Step 2 of 2: connect %s'=>'Krok 2 z 2: připojte %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Zadejte adresu své služby kompatibilní s OpenAI, končící na /v1. Klíč je vyžadován pouze v případě, že si o něj služba požádá.','Open %s and sign in (or create a free account).'=>'Otevřete %s a přihlaste se (nebo si vytvořte bezplatný účet).','the %s API keys page'=>'stránka s API klíči %s','Create a new key and copy it.'=>'Vytvořte nový klíč a zkopírujte jej.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Vložte jej níže a stiskněte „Uložit a otestovat“. Odešleme jeden malý požadavek, abychom ověřili, že to funguje.','Most providers need a little credit on the account before a key works: %s.'=>'Většina poskytovatelů vyžaduje na účtu určitý kredit, než začne klíč fungovat: %s.','add credit'=>'přidat kredit','← Choose a different provider'=>'← Zvolit jiného poskytovatele','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Uložený klíč končí na …%s — vložte nový pro jeho nahrazení','Key (optional)'=>'Klíč (volitelné)','API key'=>'API klíč','Save and test'=>'Uložit a otestovat','Providers'=>'Poskytovatelé','Provider'=>'Poskytovatel','Status'=>'Stav','Key'=>'Klíč','Get a key'=>'Získat klíč','Test'=>'Test','Remove'=>'Odebrat','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Uloženo novější verzí pluginu: aktualizujte tento plugin nebo zadejte klíč znovu.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Uložený klíč již nelze otevřít (bezpečnostní klíče webu se změněny). Zadejte jej znovu.','Not connected'=>'Nepřipojeno','Connected — last test passed %s'=>'Připojeno – poslední test úspěšný %s','Last test failed: %s'=>'Poslední test selhal: %s','Connected — not tested yet'=>'Připojeno – dosud netestováno','Which model to use'=>'Který model použít','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označuje naše doporučení pro daný úkol. Seznam obsahuje všechny modely, které váš klíč může používat, načtené živě od poskytovatele.','— Recommended for the provider —'=>'— Doporučeno pro poskytovatele —','Save models'=>'Uložit modely','Refresh the model lists from the providers'=>'Aktualizovat seznamy modelů od poskytovatelů','best quality'=>'nejvyšší kvalita','lowest cost'=>'nejnižší cena','fastest'=>'nejrychlejší','Add a model yourself'=>'Přidat model vlastními silami','A model came out today? Paste its exact name to use it straight away.'=>'Vyšel dnes nový model? Vložte jeho přesný název a můžete ho ihned začít používat.','Model name'=>'Název modelu','Add model'=>'Přidat model','Recommended models list'=>'Seznam doporučených modelů','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Seznam doporučených modelů se nepodařilo ověřit, proto se nezobrazují žádná doporučení. Přeinstalujte plugin nebo níže zapněte denní aktualizace.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Používaný seznam byl publikován dne %s. Každá aktualizace pluginu přináší nový.','Also check Zinn Digital® once a day for an updated list.'=>'Také kontrolujte Zinn Digital® jednou denně kvůli aktualizovanému seznamu.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Odesílá se pouze prostý požadavek na stažení: žádný klíč, žádná adresa webu, nic o vašem obsahu. Seznam je podepsaný a seznam, který neprojde kontrolou podpisu, je ignorován.','Last checked %1$s: %2$s.'=>'Naposledy zkontrolováno %1$s: %2$s.','Save, and check now if turned on'=>'Uložit a nyní zkontrolovat, zda je zapnuto','a newer list was installed'=>'byl nainstalován novější seznam','already up to date'=>'již aktuální','the download failed the signature check and was ignored'=>'stahování selhalo při kontrole podpisu a bylo ignorováno','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nebylo možné kontaktovat; aktuální seznam zůstává v platnosti','turned off'=>'vypnuto','Open'=>'Otevřít','Check their status page'=>'Zkontrolovat jejich stavovou stránku','Open your billing page'=>'Otevřete svou stránku fakturace','Open your API keys page'=>'Otevřete stránku s API klíči','Open the AI settings'=>'Otevřít nastavení AI','Sorry, you are not allowed to do that.'=>'Litujeme, k této akci nemáte oprávnění.','Unknown provider.'=>'Neznámý poskytovatel.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Zadejte adresu své služby, například http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To nevypadá jako klíč API. Zkopírujte ho znovu bez mezer.','Paste your API key first.'=>'Nejprve vložte svůj klíč API.','Key removed.'=>'Klíč byl odstraněn.','Models saved.'=>'Modely uloženy.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Zadejte přesný název modelu, například tak, jak je uveden v dokumentaci poskytovatele.','Added %s. Choose it under "Which model to use".'=>'Přidáno %s. Vyberte jej v části „Který model použít“.','Model removed.'=>'Model odebrán.','Daily updates are off. The list that came with the plugin is used.'=>'Denní aktualizace jsou vypnuty. Používá se seznam, který byl dodán s pluginem.','Checked: %s.'=>'Zaškrtnuto: %s.','Model lists refreshed.'=>'Seznamy modelů byly aktualizovány.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Váš AI klíč byl uložen novější verzí jednoho z vašich pluginů. Aktualizujte tento plugin nebo zadejte klíč znovu v nastavení AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Váš uložený klíč AI již nelze otevřít (bezpečnostní klíče webu se změnily). Zadejte jej znovu v nastavení AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Umělá inteligence ještě není nastavená. Přidejte klíč pro poskytovatele AI v nastavení AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Pro tuto úlohu není vybrán žádný model. Zvolte jeden v nastavení umělé inteligence.','That AI provider is not supported by this version of the plugin.'=>'Tento poskytovatel AI není touto verzí pluginu podporován.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tento web nemohl navázat spojení s vaší službou umělé inteligence. Zkontrolujte, zda je spuštěná a zda je její adresa dostupná z vašeho webového serveru (služba běžící na vašem vlastním počítači není z hostovaného webu dostupná).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tento web se nemohl připojit k serveru %s. Zkontrolujte jeho stavovou stránku; pokud funguje, váš hosting může blokovat odchozí připojení nebo je adresa nesprávná.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s uvádí, že vašemu účtu došel kredit nebo kvóta. Přidejte kredit nebo zvyšte svůj limit ve svém účtu u nich a zkuste to znovu.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s váš klíč nepřijal. Může být zapsán chybně, odvolán nebo jeho platnost vypršela. Vytvořte nový klíč a vložte jej sem.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s tuto žádost pro váš klíč odmítl. Klíč nemusí mít k tomuto modelu nebo funkci přístup, případně je nutné ověřit váš účet.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" není dostupný od poskytovatele %2$s pro váš klíč. Zvolte jiný model v nastavení AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Váš tarif %2$s nezahrnuje model „%1$s“. Vyberte v nastavení umělé inteligence jiný model, nebo si u nich svůj tarif vylepšete.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s omezuje rychlost, s jakou může váš klíč odesílat požadavky. Počkejte minutu a zkuste to znovu, nebo u nich zvyšte svůj limit požadavků.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s má právě teď problémy (výpadek nebo přetížení na jejich straně). S vaším nastavením není nic v nepořádku. Zkuste to brzy znovu.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Požadavek na AI selhal z nezjištěného důvodu. Zkuste to znovu; pokud problém přetrvává, kontaktujte podporu a uveďte podrobnosti níže.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Poskytovatel umělé inteligence odpověděl ve formátu, který tento plugin nedokáže přečíst. Zkuste to znovu; pokud to bude pokračovat, zvolte jiný model nebo kontaktujte podporu.','Custom (OpenAI-compatible)'=>'Vlastní (kompatibilní s OpenAI)','Save a key for this provider first.'=>'Nejprve uložte klíč pro tohoto poskytovatele.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Váš klíč funguje, ale poskytovatel pro něj uvádí žádný textový model. Přidejte model sami níže.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Připojeno. %1$s odpověděl(a) pomocí %2$s. Vaše funkce s umělou inteligencí jsou připraveny k použití.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaše uživatelská role nemá na tomto webu povomoženo používat umělou inteligenci. Požádejte administrátora.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tento web dosáhl svého měsíčního limitu útraty za umělou inteligenci. Správce ho může zvýšit v nastavení umělé inteligence.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tento web dosáhl svého měsíčního limitu požadavků na AI. Správce ho může navýšit v nastavení AI.','Usage and cost'=>'Využití a náklady','The log, limits and role permissions apply to AI used through: %s.'=>'Protokol, limity a oprávnění rolí platí pro AI používanou prostřednictvím: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Náklady jsou přibližné, vypočítané ze zveřejněných cen; model bez známé ceny se počítá jako nula.','This month: %1$s requests, about %2$s.'=>'Tento měsíc: %1$s požadavků, přibližně %2$s.','When'=>'Když','Who'=>'Kdo','Used for'=>'Použito pro','Model'=>'Model','Tokens in / out'=>'Tokeny na vstupu / výstupu','About'=>'O aplikaci','Result'=>'Výsledek','No AI requests have been made yet.'=>'Zatím nebyly provedeny žádné požadavky na AI.','Done'=>'Hotovo','Limits and permissions'=>'Limity a oprávnění','Monthly spending limit (US dollars)'=>'Měsíční limit útraty (v USD)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ponechte prázdné pro bez limitu. Umělá inteligence se pro zbytek měsíce zastaví, jakmile přibližné náklady dosáhnou této hodnoty.','Monthly request limit'=>'Měsíční limit požadavků','Leave empty for no limit.'=>'Ponechte prázdné pro bez omezení.','Who may use AI'=>'Kdo může používat AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Nezaškrtávejte nic, pokud chcete povolit používání umělé inteligence všem, kteří mohou používat funkce tohoto pluginu. Správci ji mohou používat vždy.','Save limits and permissions'=>'Uložit limity a oprávnění','Limits and permissions saved.'=>'Limity a oprávnění byly uloženy.','That language is not one of this site\'s languages.'=>'Tento jazyk není jedním z jazyků tohoto webu.','A translation must be the same kind of content as the original.'=>'Překlad musí být stejného typu obsahu jako originál.','Choose one of the site\'s other languages.'=>'Zvolte jeden z dalších jazyků webu.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripty administrátorské obrazovky v této kopii pluginu chybí. Přeinstalujte ho z vydaného balíčku.','This screen needs JavaScript.'=>'Tato obrazovka vyžaduje JavaScript.','Choose a language'=>'Vyberte jazyk','Upgrade'=>'Upgradovat','Pricing'=>'Ceny','Start Trial'=>'Zahájit zkušební verzi','Account'=>'Účet','Contact Us'=>'Kontaktujte nás','Affiliation'=>'Partnerská spolupráce','the kind of softwarePlugin'=>'Modul plug-in','greetingHey %s,'=>'Ahoj, %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Přihlaste se k odběru e-mailových upozornění na aktualizace zabezpečení a funkcí, vzdělávací obsah a občasné nabídky a sdílejte některé základní informace o prostředí WordPress. Pomůže nám to učinit %s kompatibilnějším s vaším webem a zajistit, aby lépe plnil to, co od něj potřebujete.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Přihlaste se k odběru e-notifikací o aktualizacích zabezpečení a funkcí, vzdělávacím obsahu a občasných nabídkách a sdílejte základní informace o prostředí WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Pokud tohle přeskočíte, nevadí to! %1$s bude stále fungovat bez problémů.','Allow & Continue'=>'Povolit a pokračovat','verbSkip'=>'Přeskočit','Skipping, please wait'=>'Přeskakuje se, prosím čekejte','Continue'=>'Pokračovat','Please wait'=>'Čekejte prosím','as activating pluginActivating'=>'Aktivuje se','This will allow %s to'=>'Tento krok umožní %s','Privacy Policy'=>'Zásady ochrany osobních údajů','Terms of Service'=>'Podmínki služby','License Agreement'=>'Licenční smlouva','Have a license key?'=>'Máte licenční klíč?','Activate License'=>'Aktivovat licenci','View Basic Profile Info'=>'Zobrazit základní informace o profilu','Your WordPress user\'s: first & last name, and email address'=>'Údaje vašeho uživatele WordPress: křestní jméno, příjmení a e-mailová adresa','View Basic Website Info'=>'Zobrazit základní informace o webu','Homepage URL & title, WP & PHP versions, and site language'=>'Adresa URL a název domovské stránky, verze WP a PHP a jazyk webu','View Basic %s Info'=>'Zobrazit základní informace o %s','Current %s & SDK versions, and if active or uninstalled'=>'Aktuální verze %s a SDK a stav (aktivní nebo odinstalováno)','Newsletter'=>'Zpravodaj','Updates, announcements, marketing, no spam'=>'Aktualizace, oznámení, marketing, žádný spam','View Diagnostic Info'=>'Zobrazit diagnostické informace','WordPress & PHP versions, site language & title'=>'Verze WordPressu a PHP, jazyk a název webu','View Plugins & Themes List'=>'Zobrazit seznam pluginů a šablon','Names, slugs, versions, and if active or not'=>'Název, identifikátory (slugs), verze a informace o tom, zda jsou aktivní, či nikoli','optional'=>'volitelné','Never miss an important update'=>'Nezmeškejte žádnou důležitou aktualizaci','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Tuto možnost jsme zavedli, abyste už nikdy nezmeškali důležitou aktualizaci a pomohli nám učinit %s kompatibilnějším s vaším webem a lepší v tom, co od něj potřebujete.','Thank you for updating to %1$s v%2$s!'=>'Děkujeme za aktualizaci na verzi %1$s %2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Předpona musí obsahovat 1 až 8 malých písmen nebo číslic, začínat písmenem a nesmí být názvem pluginu.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" není kód jazyka. Použijte národní prostředí WordPress, například fr_FR nebo de_DE.','List at least one language.'=>'Uveďte alespoň jeden jazyk.','You are not allowed to translate this item.'=>'Tuto položku není dovoleno překládat.','This item already has a version in that language.'=>'Tato položka již má verzi v tomto jazyce.','That translation engine is not available on this site.'=>'Tento překladový motor není na tomto webu k dispozici.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Různé enginy pro každý jazyk, automatická záloha a limity útrat jsou funkce Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Každý jazyk musí být jedním z jazyků stránek s dostupným enginem.','The fallback list may only name available engines.'=>'Seznam pro rezervní hodnoty může uvádět pouze dostupné enginy.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Měsíční limit je částka v US dolarech, nulová nebo vyšší, pro dostupný modul.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Preferované překlady a tón pro jednotlivé jazyky jsou funkce verze Tranzly Pro. Seznam výrazů k nepřekládání je zdarma.','Glossary entries must be grouped by one of the site\'s languages.'=>'Položky slovníku musí být seskupeny podle jednoho z jazyků webu.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'Tón se nastavuje pro každý jazyk webu: výchozí formálnost, více či méně, plus volitelné pokyny.','The value for %s is not one of the allowed choices.'=>'Hodnota pro %s nepatří mezi povolené možnosti.','The background queue is not available on this site.'=>'Na tomto webu není fronta na pozadí k dispozici.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Překladová úloha se spouští pod osobou, která ji zahajuje, takže uživatel musí být přihlášen.','There is nothing you are allowed to translate in that selection.'=>'V tomto výběru není nic, co byste směl(a) překládat.','That item is not part of a translation job.'=>'Tato položka není součástí překladové úlohy.','You are not allowed to change that translation.'=>'Nemáte povolené tuto překladovou verzi měnit.','This item\'s group already has a %1$s version (#%2$d).'=>'Skupina této položky již obsahuje verzi %1$s (#%2$d).','An item cannot be its own translation.'=>'Položka nemůže být vlastním překladem.','That item is already a translation of something else. Unlink it first.'=>'Tato položka je již překladem něčeho jiného. Nejprve ji odpojte.','The translation link could not be saved.'=>'Odkaz na překlad se nepodařilo uložit.','That text cannot be translated here.'=>'Tento text zde nelze přeložit.','That media text cannot be translated here.'=>'Tento mediální text zde nelze přeložit.','A translation can be published or kept as a draft.'=>'Překlad lze publikovat nebo uložit jako koncept.','You are not allowed to publish this kind of content.'=>'Nemáte oprávnění publikovat tento typ obsahu.','This item is already written in that language.'=>'Tato položka je již v tomto jazyce napsána.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Tento překlad byl upraven člověkem (nebo importován), takže je chráněný. Odemkněte jej, abyste jej mohli přeložit znovu.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Zatím není nastaven žádný překladový stroj. Přidejte pro něj klíč v rozhraní Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Tento překladový motor ještě není nastaven: nejprve přidejte jeho klíč.','The same text is being translated by another job right now; this item will use that answer.'=>'Tento text právě překládá jiná úloha; tato položka použije daný výsledek.','No translation engine could take this item.'=>'Žádný překladatelský stroj tuto položku nedokázal zpracovat.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'Modul nevrátil překlad pro každou část této položky. Nic nebylo změněno.','AI model'=>'Model AI','AI model (%1$s %2$s)'=>'Model AI (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s má právě teď problémy. Zkuste to brzy znovu nebo použijte jiný vyhledávač.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Vaše stránka se nemohla připojit k %s. Zkontrolujte, zda může navazovat odchozí připojení, a zkuste to znovu.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s nepřijal váš klíč API. Zkontrolujte klíč v Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Váš účet %s vyčerpal svou kvótu nebo zůstatek. Dobijte ho u nich, nebo použijte jiný engine.','%s asked us to slow down. It will be tried again automatically.'=>'%s nás požádal o zpomalení. Akce bude automaticky zopakována.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Tento text je na jedno použití v %s příliš dlouhý. Rozdělte obsah nebo použijte jiný engine.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s odmítl tento obsah přeložit. Zkuste jiný překladač nebo jej přeložte ručně.','%s does not translate this language. Choose another engine for it.'=>'%s tento jazyk nepodporuje. Vyberte pro něj jiný překladač.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Měsíční limit útrat pro %s byl dosažen, takže do něj nebylo odesláno nic dalšího. Zvyšte limit v Tranzly → Engines nebo počkejte do příštího měsíce.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'Překlad s %s selhal z důvodu, který Tranzly nedokázalo identifikovat. Podrobnosti jsou uvedeny níže.','An engine id must be lowercase letters, digits and hyphens.'=>'Identifikátor enginu se musí skládat pouze z malých písmen, číslic a pomlček.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Vytvořil Neil Lock, generální ředitel společnosti Zinn Digital® Ltd','Version %s'=>'Verze %s','Tranzly website'=>'Webová stránka Tranzly','Zinn Digital® website'=>'webová stránka Zinn Digital®','Settings saved.'=>'Nastavení uložena.','See the Pro plans and pricing'=>'Zobrazit plány a ceny Pro','Languages'=>'Jazyky','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'První jazyk je ten, ve kterém je napsán váš obsah. Návštěvníci přepínají pomocí bloku přepínače jazyků.','(default)'=>'(výchozí)','Locale code'=>'Kód národního prostředí','For example fr_FR'=>'Například fr_FR','Name (optional)'=>'Název (nepovinné)','For example Français'=>'Například Français','Add language'=>'Přidat jazyk','Front-end output'=>'Výstup front-endu','Class name prefix'=>'Předpona názvu třídy','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Každý název třídy, který plugin vypisuje na vašich stránkách, začíná tímto předponou, takže stránky neprozradí, který plugin je vytvořil. 1 až 8 malých písmen nebo čísel, začínajících písmenem.','Beta updates'=>'Beta aktualizace','This site receives beta versions as updates.'=>'Tento web přijímá jako aktualizace beta verze.','This site receives stable versions only.'=>'Tento web přijímá pouze stabilní verze.','Change this on the Account page'=>'Změňte to na stránce Účet','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta verze jsou nabízeným licencovaným instalacím Pro, které jsou propojené se svým účtem. Po propojení se můžete připojit na stránce Účet.','Save settings'=>'Uložit nastavení','First engine that is set up'=>'První nastavený engine','Key saved. It is stored encrypted and never shown again.'=>'Klíč byl uložen. Je uložen v šifrované podobě a už se nikdy nezobrazí.','Engine settings saved.'=>'Nastavení motoru uložena.','Glossary saved.'=>'Slovník byl uložen.','Your keys'=>'Vaše klíče','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly volá překladatelské služby pomocí vašeho vlastního účtu. Klíče jsou uloženy šifrovaně ve vaší databázi a jsou odesílány pouze té službě, ke které patří. Klíče modelů AI se nastavují v nastavení AI.','%s API key'=>'%s API klíč','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Uloženo: %s. Zadejte nový klíč pro nahrazení nebo uložte prázdné pole pro jeho odstranění.','No key saved.'=>'Žádný klíč nebyl uložen.','Azure region (leave empty for a global resource)'=>'Oblast Azure (ponechte prázdné pro globální prostředek)','Save key'=>'Uložit klíč','Check my DeepL usage'=>'Zkontrolovat využití DeepL','%1$s of %2$s characters used this billing period.'=>'V tomto fakturačním období bylo využito %1$s z %2$s znaků.','Which engine translates'=>'Který modul překládá','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Zatím není nastaven žádný překladač. Uložte výše klíč (nebo nastavte model AI) a začněte překládat.','Default engine'=>'Výchozí engine','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Jiný překladový engine pro každý jazyk, automatická záložní alternativa a měsíční limity útraty jsou funkce verze Tranzly Pro.','Engine for %s'=>'Modul pro %s','The default engine'=>'Výchozí engine','If an engine fails or reaches a limit, try these next, in this order'=>'Pokud některý engine selhala nebo dosáhne limitu, vyzkoušejte postupně tyto kroky v tomto pořadí','Monthly spending caps'=>'Měsíční výdajové limity','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Když motor dosáhne svého limitu, do příštího měsíce se do něj již nic neodesílá a zpráva o neúspěšném překladu uvádí důvod. Pokud limit nechcete nastavit, pole prázdné.','%1$s (spent this month: $%2$s)'=>'%1$s (utraceno tento měsíc: $%2$s)','Save caps'=>'Uložit limity','Glossary and words never translated'=>'Slovník a slova, která se nikdy nepřekládají','Never translate these words (one per line)'=>'Nikdy nepřekládejte tato slova (jedno na řádek)','Brand and product names stay exactly as they are, with every engine.'=>'Názvy značek a produktů zůstávají u každého enginu přesně takové, jaké jsou.','Preferred translations and tone per language are Tranzly Pro features.'=>'Upřednostňované překlady a tón pro jednotlivé jazyky jsou funkce Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'Preferované překlady (jeden na řádek: termín = překlad)','Formality'=>'Formálnost','Default'=>'Výchozí','Formal'=>'Formální','Informal'=>'Neformální','Style instructions (audience, brand voice)'=>'Pokyny ke stylu (cílová skupina, hlas značky)','Save glossary'=>'Uložit slovník','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Úloha byla spuštěna a zbývá v ní dokončit %d překladů. Běží na pozadí, tuto stránku můžete zavřít.','Queued again.'=>'Znovu zařazeno do fronty.','Running'=>'Spouští se','Finished'=>'Dokončeno','Cancelled'=>'Zrušeno','Translate in the background'=>'Přeložit na pozadí','Set up a translation engine in the Engines tab first.'=>'Nejprve nastavte překladový engine na kartě Engine.','Translate every'=>'Přeložit vše','Into'=>'Do','With'=>'S','Each language’s own engine'=>'Vlastní stroj pro každý jazyk','Publish the translations (otherwise they are saved as drafts)'=>'Publikujte překlady (jinak se uloží jako koncepty)','Estimate the cost'=>'Odhadnout náklady','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d příspěvků, %2$s znaků. Cena tohoto enginu není předem známa.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d příspěvků, %2$s znaků: přibližně $%3$s na vašem vlastním účtu.','Start translating'=>'Začít překládat','Jobs'=>'Úlohy','No translation jobs yet.'=>'Zatím žádné překladové úlohy.','Job %1$d — %2$s'=>'Úloha %1$d – %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d z %2$d přeloženo, %3$d selhalo, %4$d přeskočeno (chráněno nebo již v daném jazyce)','Stop this job'=>'Zastavit tuto úlohu','See what failed and why'=>'Podívejte se, co selhalo a proč','Content'=>'Obsah','Language'=>'Jazyk','What went wrong'=>'Co se pokazilo','Fix it'=>'Opravit','Details'=>'Podrobnosti','Retry with'=>'Zkusit znovu s','The same engine'=>'Stejný engine','Retry'=>'Opakovat','Translate by hand'=>'Přeložit ručně','Languages and settings'=>'Jazyky a nastavení','Engines'=>'Enginy','Translation jobs'=>'Překladové úlohy','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Přidejte druhý jazyk v nabídce administrace v sekci Tranzly a zde se zobrazí přepínač.','Switcher'=>'Přepínač','Accessible label'=>'Popis pro přístupnost','block titleLanguage switcher'=>'Přepínač jazyka','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Odkazy na tuto stránku v každém z jazyků webu. Nezobrazuje nic, dokud nejsou uvedeny dva nebo více jazyků.','block keywordlanguage'=>'Jazyk','block keywordswitcher'=>'přepínač','block keywordtranslation'=>'překlad']];